def eval_expr(s):
    tokens = _tokenize(s)
    if not tokens:
        raise ValueError("Empty expression")
    pos = 0

    def peek():
        nonlocal pos
        return tokens[pos] if pos < len(tokens) else None

    def advance():
        nonlocal pos
        t = tokens[pos]
        pos += 1
        return t

    def parse_expr():
        val = parse_term()
        while peek() in ('+', '-'):
            op = advance()
            rhs = parse_term()
            val = val + rhs if op == '+' else val - rhs
        return val

    def parse_term():
        val = parse_factor()
        while peek() in ('*', '/'):
            op = advance()
            rhs = parse_factor()
            val = val * rhs if op == '*' else val / rhs
        return val

    def parse_factor():
        t = peek()
        if t == '-':
            advance()
            return -parse_factor()
        if t == '+':
            advance()
            return parse_factor()
        return parse_atom()

    def parse_atom():
        t = advance()
        if t == '(':
            val = parse_expr()
            if peek() != ')':
                raise ValueError("Missing closing parenthesis")
            advance()
            return val
        return float(t)

    result = parse_expr()
    if pos != len(tokens):
        raise ValueError(f"Unexpected token: {tokens[pos]!r}")
    return float(result)


def _tokenize(s):
    tokens = []
    i, n = 0, len(s)
    while i < n:
        c = s[i]
        if c.isspace():
            i += 1
        elif c.isdigit():
            j = i
            while j < n and s[j].isdigit():
                j += 1
            tokens.append(int(s[i:j]))
            i = j
        elif c in '+-*/()':
            tokens.append(c)
            i += 1
        else:
            raise ValueError(f"Unexpected character: {c!r}")
    return tokens
