def topo_count(n, edges):
    pred = [0] * n
    for u, v in edges:
        pred[v] |= 1 << u
    dp = [0] * (1 << n)
    dp[0] = 1
    for mask in range(1 << n):
        if dp[mask] == 0:
            continue
        for u in range(n):
            bit = 1 << u
            if (mask & bit) == 0 and (pred[u] & mask) == pred[u]:
                dp[mask | bit] += dp[mask]
    return dp[(1 << n) - 1]
